/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountSpoilerReveal, type SpoilerRevealOptions } from "../../components/spoiler-reveal/SpoilerRevealEngine.js";
import type { MotionController } from "../../components/spoiler-reveal/motion-runtime";

export function SpoilerReveal({ options, className }: { options?: SpoilerRevealOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountSpoilerReveal(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="spoiler-reveal" />;
}

